fn fixture()->BitmapSnapshot{let f:serde_json::Value=serde_json::from_str(fixture_text!("../../🏅️standards/🔖️1/🪆️subsets/✳️any/🚪️io/🪶️sqlite/📸️snapshot/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();BitmapSnapshot{schema:f["schema"].as_str().unwrap().into(),seed:f["seed"].as_str().unwrap().parse().unwrap(),input:BitmapInput{width:f["input"]["width"].as_u64().unwrap() as u32,height:f["input"]["height"].as_u64().unwrap() as u32,palette:f["input"]["palette"].as_array().unwrap().iter().map(|c|BitmapColor{r:c["r"].as_u64().unwrap() as u32,g:c["g"].as_u64().unwrap() as u32,b:c["b"].as_u64().unwrap() as u32,a:c["a"].as_u64().unwrap() as u32}).collect(),pixels:crate::standards::v1::subsets::any::io::text::snapshot::decode_base64(f["input"]["pixels"].as_str().unwrap()).unwrap()},output:BitmapOutputSpec{width:f["output"]["width"].as_u64().unwrap() as u32,height:f["output"]["height"].as_u64().unwrap() as u32,periodic:true},model:BitmapOverlappingModel{pattern_size:u32::MAX,symmetry:8,periodic_input:false,ground:Some(u32::MAX)},pinned:vec![BitmapPinnedPixel{x:u32::MAX,y:1,color:u32::MAX},BitmapPinnedPixel{x:0,y:0,color:0}]}}
fn project(s:&BitmapSnapshot)->SqliteDatabase{original_owners::with_sqlite_recipient(SqliteDatabaseLimits::default(),&mut |_|true,|sqlite_control|s.to_sqlite_database(sqlite_control)).unwrap()}
fn restore(d:&SqliteDatabase)->Result<BitmapSnapshot,semio_framework_value::ValueError>{original_owners::with_sqlite_recipient(SqliteDatabaseLimits::default(),&mut |_|true,|sqlite_control|BitmapSnapshot::from_sqlite_database(d, sqlite_control))}
#[test]fn sqlite_snapshot_wfc_bitmap_all_native_fields(){let s=fixture();let d=project(&s);assert_eq!(d.tables.len(),6);let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let actual=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(actual,s);assert_eq!(pack::snapshot::ArtifactPack::encode_pack(&actual),pack::snapshot::ArtifactPack::encode_pack(&s));assert_eq!(pack::snapshot::ArtifactDsl::print_dsl(&actual),pack::snapshot::ArtifactDsl::print_dsl(&s));let mut arbitrary=s;arbitrary.input.pixels=b"invalid native scalar".to_vec();arbitrary.input.palette.clear();arbitrary.model.ground=None;assert_eq!(restore(&project(&arbitrary)).unwrap(),arbitrary);}
#[test]fn sqlite_snapshot_wfc_bitmap_independent_query_and_edit(){use std::io::Write;use std::process::{Command,Stdio};let s=fixture();let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const p=d.query('SELECT red,palette_indices FROM wfc_bitmap_palette JOIN wfc_bitmap_input ON document_id=wfc_bitmap_input.id ORDER BY ordinal').all();if(p.length!==2||p[0].red!==4294967295||Buffer.from(p[0].palette_indices).toString('hex')!=='0001')throw Error('fields');d.query('UPDATE wfc_bitmap_pin SET x=7 WHERE ordinal=1').run();await Bun.write(Bun.stdout,d.serialize());";let mut c=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();c.stdin.take().unwrap().write_all(&bytes).unwrap();let o=c.wait_with_output().unwrap();assert!(o.status.success(),"{}",String::from_utf8_lossy(&o.stderr));let mut expected=s;expected.pinned[1].x=7;assert_eq!(restore(&import_sqlite_database(&o.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap(),expected);}
#[test]fn sqlite_snapshot_wfc_bitmap_invalid_relations_limits_cancellation(){let d=project(&fixture());for n in 0..5{let mut m=d.clone();match n{0=>m.table_mut("wfc_bitmap_pin").unwrap().rows[0].values[1]=SqliteValue::Integer(2),1=>m.table_mut("wfc_bitmap_palette").unwrap().rows[0].values[2]=SqliteValue::Integer(9),2=>m.table_mut("wfc_bitmap_output").unwrap().rows[0].values[3]=SqliteValue::Integer(2),3=>m.table_mut("wfc_bitmap_model").unwrap().rows[0].values[1]=SqliteValue::Integer(-1),_=>m.table_mut("wfc_bitmap_document").unwrap().rows[0].values[2]=SqliteValue::Text("01".into())};assert!(restore(&m).is_err());}assert!(original_owners::with_sqlite_recipient(SqliteDatabaseLimits::default(),&mut |_|false,|sqlite_control|fixture().to_sqlite_database(sqlite_control)).is_err());assert!(original_owners::with_sqlite_recipient(SqliteDatabaseLimits{max_value_bytes:4,..SqliteDatabaseLimits::default()},&mut |_|true,|sqlite_control|BitmapSnapshot::from_sqlite_database(&d, sqlite_control)).is_err());let mut s=fixture();s.input.pixels=vec![120;100000];assert!(original_owners::with_sqlite_recipient(SqliteDatabaseLimits::default(),&mut |p|p.phase!=SqliteSnapshotPhase::ProjectSnapshot||p.completed==0,|sqlite_control|s.to_sqlite_database(sqlite_control)).is_err());}
#[test]fn sqlite_snapshot_wfc_bitmap_actual_owner_native_admission(){let s=fixture();let codec=crate::standards::v1::subsets::any::io::io().native.codec;let provider=codec.snapshot_sqlite.unwrap();let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.wfc.bitmap".into(),standard:"1".into(),subset:"*".into()};for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let actual=original_owners::with_encoding(|native_owner|(provider.import)("bitmap",&dialect, &mut Some(project(&s)),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap().value;let expected=match encoding{SnapshotEncoding::Binary=>store::io::IoPayload::Binary(pack::snapshot::ArtifactPack::encode_pack(&s)),SnapshotEncoding::Text=>store::io::IoPayload::Text(pack::snapshot::ArtifactDsl::print_dsl(&s))};assert_eq!(actual,expected);assert!(s.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()})).is_err());}let invalid=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.wfc.bitmap".into(),standard:"1".into(),subset:"named".into()};assert!(s.validate_sqlite_snapshot_subset(&invalid,&project(&s),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}

#[test]fn sqlite_snapshot_bitmap_declared_erased_roundtrip_both_native_encodings(){let source=fixture();let codec=crate::standards::v1::subsets::any::io::io().native.codec;let schema=codec.schema.clone();let provider=codec.snapshot_sqlite.unwrap();let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.wfc.bitmap".into(),standard:"1".into(),subset:"*".into()};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::io::IoPayload::Binary(<BitmapSnapshot as pack::snapshot::ArtifactPack>::encode_pack(&source)),SnapshotEncoding::Text=>store::io::IoPayload::Text(<BitmapSnapshot as pack::snapshot::ArtifactDsl>::print_dsl(&source))};let d=original_owners::with_decoding(|native_owner|(provider.export)(&schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap().value;assert_eq!(project(&restore(&d).unwrap()),project(&source));let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let database=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();assert_eq!(original_owners::with_encoding(|native_owner|(provider.import)(&schema,&dialect, &mut Some(database),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap().value,payload);}}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_bitmap_actual_owned_io_declaration_codec(){use semio_framework_os_kernel::io::{register_native_snapshot_codec,io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot}};register_native_snapshot_codec(crate::WFC_BITMAP_DIALECT,crate::standards::v1::subsets::any::io::io().native.codec).unwrap();let source=fixture();let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.wfc.bitmap".into(),standard:"1".into(),subset:"*".into()};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut phases=Vec::new();let bytes=async{let original_file_dialect=&dialect;let original_file_input=&source;let original_file_encoding=encoding;let original_file_limits=SqliteDatabaseLimits::default();let original_file_progress:&mut dyn FnMut(semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress)->bool=&mut |p|{phases.push(p.phase);true};semio_framework_os_kernel::io::testing::with_snapshot_file_decoding(semio_framework_os_kernel::io::testing::ORIGINAL_FILE_CALLER,original_file_limits,original_file_progress,async|sqlite_control,native_owner|io_export_sqlite_snapshot(original_file_dialect,original_file_input,original_file_encoding,sqlite_control,native_owner).await).await}.await.unwrap().value;let back=async{let original_file_dialect=&dialect;let original_file_input=&bytes;let original_file_limits=SqliteDatabaseLimits::default();let original_file_progress:&mut dyn FnMut(semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress)->bool=&mut |_|true;semio_framework_os_kernel::io::testing::with_snapshot_file_encoding(semio_framework_os_kernel::io::testing::ORIGINAL_FILE_CALLER,original_file_limits,original_file_progress,async|sqlite_control,native_owner|io_import_sqlite_snapshot::<BitmapSnapshot>(original_file_dialect,original_file_input,sqlite_control,native_owner).await).await}.await.unwrap().value;assert_eq!(project(&back),project(&source));assert!(!phases.iter().any(|p|matches!(p,SqliteSnapshotPhase::DecodeNative|SqliteSnapshotPhase::EncodeNative)));}}

#[test]
fn sqlite_snapshot_bitmap_explicit_controlled_native_owner(){
 let source=fixture();for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::io::IoPayload::Binary(<BitmapSnapshot as pack::snapshot::ArtifactPack>::encode_pack(&source)),SnapshotEncoding::Text=>store::io::IoPayload::Text(<BitmapSnapshot as pack::snapshot::ArtifactDsl>::print_dsl(&source))};let actual=original_owners::with_decoding(|native_owner|BitmapSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap();assert_eq!(actual,source);assert!(original_owners::with_decoding(|native_owner|BitmapSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default()), native_owner)).is_err());assert!(original_owners::with_decoding(|native_owner|BitmapSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:16,..SqliteDatabaseLimits::default()}), native_owner)).is_err());}
}

#[test]
fn sqlite_snapshot_bitmap_controlled_native_interior_and_large_copy(){
 let f:serde_json::Value=serde_json::from_str(fixture_text!("../../🏅️standards/🔖️1/🪆️subsets/✳️any/🚪️io/🪶️sqlite/📸️snapshot/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let n=f["controlledAdmission"]["collectionItems"].as_u64().unwrap() as usize;let cancel=f["controlledAdmission"]["cancelAfter"].as_u64().unwrap() as usize;let mut source=fixture();source.input.palette=vec![source.input.palette[0].clone();n];source.pinned=vec![source.pinned[0].clone();n];for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::io::IoPayload::Binary(<BitmapSnapshot as pack::snapshot::ArtifactPack>::encode_pack(&source)),SnapshotEncoding::Text=>store::io::IoPayload::Text(<BitmapSnapshot as pack::snapshot::ArtifactDsl>::print_dsl(&source))};assert_eq!(original_owners::with_decoding(|native_owner|BitmapSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap(),source);let mut interior=false;let error=original_owners::with_decoding(|native_owner|BitmapSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |p|{if p.phase==SqliteSnapshotPhase::DecodeNative&&p.total==n&&p.completed==cancel{interior=true;false}else{true}},SqliteDatabaseLimits::default()), native_owner)).unwrap_err();assert!(interior);assert_eq!(error.kind,semio_framework_value::ValueRefusalKind::Canceled);}
 source.input.pixels=vec![120;f["controlledAdmission"]["largeTextBytes"].as_u64().unwrap() as usize];for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::io::IoPayload::Binary(<BitmapSnapshot as pack::snapshot::ArtifactPack>::encode_pack(&source)),SnapshotEncoding::Text=>store::io::IoPayload::Text(<BitmapSnapshot as pack::snapshot::ArtifactDsl>::print_dsl(&source))};assert!(original_owners::with_decoding(|native_owner|BitmapSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:f["controlledAdmission"]["smallOwnedBytes"].as_u64().unwrap() as usize,..SqliteDatabaseLimits::default()}), native_owner)).is_err());}
}

#[test]
fn sqlite_snapshot_bitmap_explicit_controlled_native_output(){
 let f:serde_json::Value=serde_json::from_str(fixture_text!("../../🏅️standards/🔖️1/🪆️subsets/✳️any/🚪️io/🪶️sqlite/📸️snapshot/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let state=&f["ownedSparseState"];let mut sparse=fixture();sparse.schema=state["schema"].as_str().unwrap().into();sparse.input.pixels=state["pixels"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap() as u8).collect();assert!(state["ground"].is_null());assert!(state["palette"].as_array().unwrap().is_empty());assert!(state["pinned"].as_array().unwrap().is_empty());sparse.input.palette.clear();sparse.pinned.clear();sparse.model.ground=None;
 for source in[fixture(),BitmapSnapshot::default(),sparse]{
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let expected=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(pack::snapshot::ArtifactPack::encode_pack(&source)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(pack::snapshot::ArtifactDsl::print_dsl(&source))};
  assert_eq!(original_owners::with_encoding(|native_owner|source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap(),expected);
  assert!(original_owners::with_encoding(|native_owner|source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default()), native_owner)).is_err());
  assert!(original_owners::with_encoding(|native_owner|source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()}), native_owner)).is_err());
 }
 }
}

#[test]
fn sqlite_snapshot_bitmap_output_real_collection_and_unicode_frontiers(){
 let f:serde_json::Value=serde_json::from_str(fixture_text!("../../🏅️standards/🔖️1/🪆️subsets/✳️any/🚪️io/🪶️sqlite/📸️snapshot/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 let n=f["controlledAdmission"]["collectionItems"].as_u64().unwrap() as usize;
 let cancel=f["controlledAdmission"]["cancelAfter"].as_u64().unwrap() as usize;
 let bytes=f["controlledAdmission"]["largeTextBytes"].as_u64().unwrap() as usize;
 let mut source=fixture();source.input.palette=vec![source.input.palette[0].clone();n];source.pinned=vec![source.pinned[0].clone();n];
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let mut interior=false;
  let error=original_owners::with_encoding(|native_owner|source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |p|{if p.phase==SqliteSnapshotPhase::EncodeNative&&p.total==n&&p.completed==cancel{interior=true;false}else{true}},SqliteDatabaseLimits::default()), native_owner)).unwrap_err();
  assert!(interior);assert_eq!(error.kind,semio_framework_value::ValueRefusalKind::Canceled);
  assert!(original_owners::with_encoding(|native_owner|source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:2*n+3,..SqliteDatabaseLimits::default()}), native_owner)).is_err());
 }
 source.input.pixels=vec![120;bytes];
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let mut interior=false;
  let error=original_owners::with_encoding(|native_owner|source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |p|{if p.phase==SqliteSnapshotPhase::EncodeNative&&p.total>=65536&&p.completed>=65536&&p.completed<p.total{interior=true;false}else{true}},SqliteDatabaseLimits::default()), native_owner)).unwrap_err();
  assert!(interior);assert_eq!(error.kind,semio_framework_value::ValueRefusalKind::Canceled);
  assert!(original_owners::with_encoding(|native_owner|source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:f["controlledAdmission"]["smallOwnedBytes"].as_u64().unwrap() as usize,..SqliteDatabaseLimits::default()}), native_owner)).is_err());
 }
}
